namespace elit21::shopify::webhooks {ShopWebhookHandler::ShopWebhookHandler():platform::BusinessComponent("ShopWebhookHandler","Persistent Shopify webhook domain handler",platform::BusinessComponentSpec{"shopify","handle_webhook",{},true,false,16U*1024U*1024U}){}ShopWebhookHandler::ShopWebhookHandler(Database&database):ShopWebhookHandler(){database_=&database;}Result<void>ShopWebhookHandler::handle(const ShopifyWebhook&event){if(!database_)return Result<void>::failure("ShopWebhookHandler is not bound to Database");return persistWebhookTask(*database_,event,{ShopifyWebhookTopic::shop_redact,ShopifyWebhookTopic::app_uninstalled});}platform::OperationResult ShopWebhookHandler::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["database_bound"]=database_?1.0:0.0;r.attributes["handler"]="ShopWebhookHandler";return r;}}
